<script lang="ts">
  import { getChildrenViewModeProps, LayoutContext } from "$lib/components/composites/dynamic-layout";
  import type { Snippet } from "svelte";
  import {
    additionalContext,
    openEditNodeDialog,
    openChangeParentDialog,
    openAddNewNodeDialog
  } from "$lib/state/app-state.svelte.js";
  import LucideIcon from "$lib/components/composites/lucide-svelte-icons/LucideIcon.svelte";
  import {
    type ChildrenViewMode,
    type DynamicLayoutNode,
    getLabel
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { Button } from "$lib/components/ui/button";
  import SvelteBoundary from "$lib/components/composites/SvelteBoundary.svelte";

  interface $$Props {
    layoutContext: LayoutContext;
    element: Snippet;
  }

  let { layoutContext, element }: $$Props = $props();

  let node = $derived(layoutContext.node);
  let elementProps = $derived(node.layoutData?.elementProps ?? {});

  function isChildrenNode (node?: DynamicLayoutNode): node is DynamicLayoutNode & { nodeConfig: ChildrenViewMode } {
    return node?.type === "children";
  }
</script>


{#snippet hoverMenuOrElement ()}
  {#if !additionalContext.editMode}
    <SvelteBoundary label="render element()">
      {@render element()}
    </SvelteBoundary>
  {:else}
    {@const parent = layoutContext.nodeInformations.parent}

    <div class="highlight-area" class:root_node={layoutContext.node === layoutContext.nodeInformations.root}>
      <div style="display: inline-flex; gap: 0.25rem">
        Type: {node.type}

        {#if isChildrenNode(parent)}
          {#if parent.nodeConfig.type === "grid"}
            {@const gridProps = node.layoutData.forParent?.grid}
            - Row: {gridProps?.row}
            {#if (gridProps?.rowSpan ?? 0) > 1}
              - [Span: {gridProps?.rowSpan}]
            {/if}
            , Col: {gridProps?.col}

            {#if (gridProps?.colSpan ?? 0) > 1}
              - [Span: {gridProps?.colSpan}]
            {/if}
          {:else}
            - Order: {node.order}
          {/if}
        {/if}

        {#if isChildrenNode(node)}
          {@const childrenProps = getChildrenViewModeProps(node)}

          - Mode: {childrenProps.type}
        {/if}

        <Button size="icon-sm" variant="secondary" class="h-6 w-6 show-pointer"
                onclick={() => {openEditNodeDialog(layoutContext)}}>
          <LucideIcon iconName="Pencil" size="16" color="white"
                      style="display: inline-block; "
          ></LucideIcon>
        </Button>
        <Button size="icon-sm" variant="secondary" class="h-6 w-6 show-pointer"
                onclick={() => {openChangeParentDialog(layoutContext)}}>
          <LucideIcon iconName="ArrowUpRight" size="16" color="white"
                      style="display: inline-block; "
          ></LucideIcon>
        </Button>

        {#if additionalContext.editMode
        && (layoutContext.node.type === "children" || layoutContext.node.type === "tab" || layoutContext.node.type === "collapsible")
        }
          <Button title="Add a new child in {getLabel(layoutContext.node)}"
                  size="icon-sm" class="h-6 w-6 show-pointer"
                  onclick={() => openAddNewNodeDialog(layoutContext)}>
            <LucideIcon iconName="Plus" size="20" color="white">
            </LucideIcon>
          </Button>
        {/if}
      </div>

      {@render element()}
    </div>
  {/if}
{/snippet}

{@render hoverMenuOrElement()}


<style>
   .highlight-area {
      display: inline-block;
      border: 2px solid transparent;
      padding-left: 1rem;
      width: 100%;

      &:hover {
         background: rgba(26, 26, 26, 0.2);
         border: 2px solid fuchsia;
      }
   }

   .root_node {
      background: rgba(26, 26, 26, 0.1);
   }

   .edit-mode {
      display: inline-flex;
      flex-grow: 0;
      gap: 0.25rem;


      &.children:hover {
         background: rgba(40, 67, 53, 0.6);
      }

      :global(.lucide-icon):hover {
         cursor: pointer;
         stroke: red;
      }
   }
</style>
