<script lang="ts">
  import {
    childrenViewModeItem,
    childrenViewModePanel,
    DynamicLayout,
    getNodeClassName,
    LayoutContext,
    sortChildrenByOrder
  } from "$lib/components/composites/dynamic-layout";
  import type {
    DashboardLayoutNode,
    DynamicLayoutNode
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import type { Snippet } from "svelte";
  import { styleTagString } from "$lib/blocks/html-utils/styleTagString";
  import { getCachedByParentNodeQuery } from "$lib/components/dashboard-nodes/helpers/cachedQueries.svelte.js";
  import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";
  import { components } from "$lib/dynamic_layout_test/all_components.svelte.js";
  import { additionalContext } from "$lib/state/app-state.svelte.js";
  import SvelteBoundary from "$lib/components/composites/SvelteBoundary.svelte";
  import DivNode from "$lib/components/composites/dynamic-layout/DivNode.svelte";
  import DashboardNode from "./DashboardNode.svelte";
  import DebugDetailsConfigPanel from "$lib/components/composites/debug-details/DebugDetailsConfigPanel.svelte";
  import DebugDetails from "$lib/components/composites/debug-details/DebugDetails.svelte";
  import { EditModeLayoutContext } from "$lib/contexts/EditModeLayoutContext";

  let props: {
    node: DashboardLayoutNode;
  } = $props();

  let layoutContext = $state<LayoutContext | null>(null);

  layoutContext = new EditModeLayoutContext({
    node: props.node,
    root: props.node,
    depth: 0
  }, {
    components,
    renderChildren: renderChildren,
    renderChildNode: renderChildNode,
    genericRenderChildren
  }, additionalContext);


</script>


{#snippet genericRenderChildren (_layoutContext: LayoutContext, nodes: DynamicLayoutNode[], wrapChild: Snippet<[LayoutContext, DashboardLayoutNode]>, sourceCall = 'noop')}
  {#snippet internalRenderChildrenByArray (_layoutContext: LayoutContext, children: DashboardLayoutNode[])}
    {@const panelClassName = getNodeClassName(_layoutContext, 'panel')}
    {@const childrenViewModePanelStyle = childrenViewModePanel(_layoutContext.node, children)}

    {@html styleTagString(panelClassName, childrenViewModePanelStyle)}

    <DebugDetails category="+page/genericRenderChildren"
                  pairs={{"ID": _layoutContext.node.id, "Type": _layoutContext.node.type, "ContextType": _layoutContext.ContextType, "Children": children.length}}
                  entries={[{ "key": "node", value: _layoutContext.node}, { "key": "children", value: children}]}
    />

    <div class={[panelClassName, 'panel', 'type__'+_layoutContext.node.type]}>
      {#each sortChildrenByOrder(children) as childNode (childNode.layoutData.forParent?.customKey ?? childNode.id)}
        {@const itemClassName = getNodeClassName(_layoutContext, 'item', childNode)}
        {@const childrenViewModeItemStyle = childrenViewModeItem(_layoutContext.node, childNode)}

        {@html styleTagString(itemClassName, childrenViewModeItemStyle)}

        <div class={[itemClassName, 'node', 'type__'+childNode.type]}>

          <DebugDetails category="+page/genericRenderChildrenEach"
                        pairs={{"ID": childNode.id, "Type": childNode.type, "ContextType": _layoutContext.ContextType}}
                        entries={[{ "key": "node", value: childNode}]}
          />

          {@render wrapChild(_layoutContext, childNode)}
        </div>
      {/each}
    </div>

    {#if children.length === 0}
      <div class="panel panel--empty">
        <div class="empty">No child nodes, use the edit mode to add some!</div>
      </div>
    {/if}
  {/snippet}

  {#if nodes?.length}
    {@render internalRenderChildrenByArray(_layoutContext, nodes)}
  {:else}
    {@const currentNodes = getCachedByParentNodeQuery(_layoutContext.node.id)}
    {@const mappedNodes = currentNodes.rows.map(n => convertDbNodeToDynamicLayoutNode(n))}

    {@render internalRenderChildrenByArray(_layoutContext, mappedNodes)}
  {/if}
{/snippet}

{#snippet renderChildren (_layoutContext: LayoutContext, sourceCall = 'noop')}
  {#snippet wrapChild (_layoutContext: LayoutContext, childNode: DynamicLayoutNode)}
    {@const newNode = _layoutContext.subNode(childNode)}

    <DebugDetails category="+page/wrapChild"
                  pairs={{"ID": childNode.id, "Type": childNode.type, "ContextType": _layoutContext.ContextType}}
                  entries={[{ "key": "node", value: childNode}]}
    />

    <DebugDetails category="+page/wrapChild/newNode"
                  pairs={{"ID": newNode.node.id, "Type": newNode.node.type, "ContextType": _layoutContext.ContextType}}
                  entries={[{ "key": "node", value: newNode.node}]}
    />

    {@render _layoutContext.render.renderChildNode(newNode)}
  {/snippet}

  {@render genericRenderChildren(_layoutContext, _layoutContext.node.children ?? [], wrapChild, '+page/renderChildren by source: ' + sourceCall)}
{/snippet}

{#snippet renderChildNode (_layoutContext: LayoutContext)}
  {@const _node = _layoutContext.node}

  {#snippet _element ()}
    <div class="node__content {_node.type}">

      <DebugDetails category="+page/_element"
                    pairs={{"ID": _node.id, "Type": _node.type, "ContextType": _layoutContext.ContextType}}
                    entries={[{ "key": "node", value: _node}]}
      />


      <SvelteBoundary>
        {#if components[_node.type]}
          {@const Component = components[_node.type]}
          <Component layoutContext={_layoutContext} />
        {:else}
          <DivNode unknownMode={true}
                   layoutContext={_layoutContext}>

          </DivNode>
        {/if}
      </SvelteBoundary>
    </div>
  {/snippet}

  <DashboardNode layoutContext={_layoutContext} element={_element} />
{/snippet}

<div class="flex flex-row">

  {#if additionalContext.DEBUG_MODE}
    <div style="white-space: nowrap">
      <DebugDetailsConfigPanel />
    </div>
  {/if}

  <SvelteBoundary>
    {#if layoutContext?.node}
      <DynamicLayout node={layoutContext.node} {components} {layoutContext} {renderChildNode}>

      </DynamicLayout>
    {/if}
  </SvelteBoundary>
</div>
