<script lang="ts">
  import CollapsibleAnimated from "./CollapsibleAnimated.svelte";
  import type { Snippet } from "svelte";
  import { flashElement } from "$lib/blocks/html-utils/flashElement";

  interface Props {
    children: Snippet;
    label?: string;
  }

  let props:Props = $props();

  function parseStackTrace (_error: unknown) {
    const typedError = _error as Error;
    const svelteStack = typedError.message.split("\n").map((line) => line.replace(" in ", "").trim()).filter(Boolean);
    const jsStack = typedError.stack?.split("\n")
      .map((line) => {
        const cleaned = line
          // cleanup all the noise
          .replaceAll("</<.children<", " ==> ")
          .replace("/</", "")
          .replace("/<@", "")
          .replace("@htt", " htt")
          .replace("/ ==> / ==>", "/ ==>")
          .replace("/ ==>", " ==>")
          .replace("_page/", "_page ==> ")
          .replace("<http", " http")
          .replace("< http", " http")
          .replaceAll("  ", " ")
          .trim();

        if (cleaned.includes("node_modules")) {
          return "";
        }

        const splittedByColon = cleaned.split(":");

        const columnNumber = splittedByColon.pop();
        const lineNumber = splittedByColon.pop();

        return cleaned.replace(`:${lineNumber}:${columnNumber}`, " at Ln " + lineNumber + " Col " + columnNumber);
      })
      .filter(l => l.length !== 0) ?? [];

    const error = svelteStack.shift();

    return { error, svelteStack, jsStack };
  }

  let errorDiv = $state<HTMLElement | null>(null);

  $effect(() => {
    if (errorDiv) {
      flashElement(errorDiv);
    }
  })
</script>

<svelte:boundary>
  {@render props.children()}

  {#snippet failed (error, reset)}
    <h3>{props.label}</h3>

    {@const stacktrace = parseStackTrace(error)}
    <div style="border: 2px dotted red" bind:this={errorDiv}>
      <span class="font-bold">Error: {stacktrace.error}</span>

      <button onclick={reset}>oops! try again</button>

      <CollapsibleAnimated buttonLabel="Show Stack" open={false}>
        <pre>{JSON.stringify(stacktrace.svelteStack, undefined, 2)}</pre>
        <pre>{JSON.stringify(stacktrace.jsStack, undefined, 2)}</pre>
      </CollapsibleAnimated>
    </div>
  {/snippet}
</svelte:boundary>
