import {
  createChildrenNode,
  createDynamicNode,
  createTabNode,
  createTextNode
} from "$lib/dynamic_layout_test/staticNodeFunctions";

export const DynamicNodes = createTabNode({
  layoutData: {
    label: "Dynamic Nodes WIP"
  },
  children: [
    createTextNode({
      nodeConfig: {
        contentType: "markdown",
        content: [
          `## This is probably the best feature of this Dashboard, Dynamic Nodes`,
          "",
          "You can either have -global- data sources to be used across multiple Dynamic Nodes, or have a -local- data source (inside one Dynamic Node)",
          "",
          "Using this data source as payload, you can create dynamic bundles of nodes with that payload for properties...",
          "",
          "### Example using the following placeholder",
          "```{{ scope.val.Title }}```"
        ].join("\n")
      }
    }),
    createDynamicNode({
      nodeConfig: {
        globalDataSource: "",
        dynamicSourceMode: "payloadFields",
        payloadFields: [
          {
            label: "Title",
            type: "string"
          },
          {
            label: "Content",
            type: "string"
          }
        ],
        layout: {
          id: "tabs",
          type: "children"
        },
        dynamicData: [
          {
            Title: "Dynamic Node 1",
            Content: "This is the content of the first dynamic node"
          },
          {
            Title: "Dynamic Node 2",
            Content: "This is the content of the second dynamic node"
          },
          {
            Title: "Dynamic Node 3",
            Content: "This is the content of the third dynamic node"
          }
        ]
      },
      children: [
        createChildrenNode({
          nodeConfig: {
            type: "rows"
          },
          children: [
            createTextNode({
              nodeConfig: {
                contentType: "markdown",
                content: "## {{ scope.val.Title }}"
              }
            })
          ]
        })
      ]
    }),
    createTextNode({
      nodeConfig: {
        contentType: "markdown",
        content: [
          `## This also works in recursion`,
          "",
          "TODO more better examples",
          "",
          "## So whats the big deal?",
          "",
          "Currently the dataSources are just static arrays, but at a later point, this could be filled from an API, or WebSocket or custom Code you are running",
          "",
          "That way the Dashboard can be anything you want, using the content or custom widgets using a specific payload and so on..."
        ].join("\n")
      }
    }),
  ]
});
