<script lang="ts">
  import { SHOW_CATEGORIES, ALL_CATEGORIES } from "./DebugDetails.svelte";
  import { Switch } from "$lib/components/ui/switch";
  import { syncToState } from "$lib/blocks/svelte-utils/localStorageSync.svelte";
  import { SvelteMap } from "svelte/reactivity";

  syncToState("debug-details-show-categories",
    () => [...SHOW_CATEGORIES.entries()],
    (strOrNull) => JSON.parse(strOrNull ?? "[]").forEach(([key, value]) => SHOW_CATEGORIES.set(key, value))
  );

  const GROUPS = $derived(Object.groupBy(ALL_CATEGORIES.entries(), ([category]) => category.split("/")[0].toUpperCase()));

  const ALL_ACTIVE_BY_GROUP = $derived.by(() => {
    const result: Record<string, boolean> = {};


    for (const [group, categories] of Object.entries(GROUPS)) {
      let allCategoriesActive = true;

      // need to be written in this way to let the svelte reactivity do its magic
      for (const [category] of categories) {
        if (!SHOW_CATEGORIES.get(category)) {
          allCategoriesActive = false;
          break;
        }
      }

      result[group] = allCategoriesActive;

    }

    return result;
  });

  function setAllActiveByGroup (group: string, active: boolean) {
    for (const [category] of GROUPS[group]) {
      SHOW_CATEGORIES.set(category, active);
    }
  }
</script>

{#each Object.entries(GROUPS) as [group, categories]}


  <h2>
    {group}

    <Switch bind:checked={() => ALL_ACTIVE_BY_GROUP[group], (v) => setAllActiveByGroup(group, v)}>

    </Switch>
  </h2>
  {#each categories as [category, show]}
    {category}:
    <Switch bind:checked={() => SHOW_CATEGORIES.get(category), (v) => SHOW_CATEGORIES.set(category, v)}>

    </Switch>

    <br />
  {/each}

  <br />
{/each}
